"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { ChevronRight } from "lucide-react";

const PinterestIcon = ({ size = 16 }: { size?: number }) => (
    <svg width={size} height={size} viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
        <circle cx="12" cy="12" r="12" fill="#E60023" />
        <path
            d="M12.017 4.5c-4.138 0-7.5 3.362-7.5 7.5 0 3.174 1.974 5.886 4.761 6.976-.065-.593-.124-1.502.026-2.15l.879-3.729s-.224-.45-.224-1.114c0-1.043.604-1.821 1.357-1.821.64 0 .949.48.949 1.056 0 .643-.409 1.605-.621 2.497-.177.746.374 1.356 1.111 1.356 1.333 0 2.357-1.405 2.357-3.434 0-1.795-1.29-3.051-3.132-3.051-2.134 0-3.386 1.6-3.386 3.255 0 .644.248 1.336.558 1.711.061.074.07.14.052.216l-.208.85c-.033.138-.109.167-.251.101-.937-.436-1.523-1.805-1.523-2.906 0-2.365 1.719-4.538 4.956-4.538 2.601 0 4.624 1.854 4.624 4.332 0 2.585-1.63 4.665-3.892 4.665-.76 0-1.474-.394-1.719-.861l-.467 1.783c-.169.652-.626 1.469-.933 1.966.702.217 1.448.334 2.221.334 4.138 0 7.5-3.362 7.5-7.5s-3.362-7.5-7.5-7.5z"
            fill="white"
        />
    </svg>
);

const Sidebar = () => {
    const pathname = usePathname();

    const menuItems = [
        {
            name: "Best Pinterest Keywords",
            href: "/keywords",
            icon: PinterestIcon,
        },
    ];

    return (
        <aside className="w-64 border-r border-border h-[calc(100vh-5rem)] sticky top-20 hidden lg:block bg-background/50 backdrop-blur-sm">
            <div className="p-6">
                <div className="mb-8">
                    <p className="text-[10px] font-black uppercase tracking-[0.2em] text-secondary opacity-50 mb-4">
                        Discover
                    </p>
                    <nav className="space-y-1">
                        {menuItems.map((item) => {
                            const Icon = item.icon;
                            const isActive = pathname === item.href;

                            return (
                                <Link
                                    key={item.href}
                                    href={item.href}
                                    className={`group flex items-center justify-between px-4 py-1.5 font-black uppercase tracking-widest transition-all duration-300 border ${isActive
                                        ? "bg-foreground text-background border-foreground"
                                        : "hover:bg-zinc-100 dark:hover:bg-zinc-900 border-transparent hover:border-border"
                                        }`}
                                >
                                    <div className="flex items-center gap-4">
                                        <div className="shrink-0 text-center">
                                            <Icon size={30} />
                                        </div>
                                        <span className="text-[8px] font-black leading-tight max-w-[120px]">
                                            {item.name}
                                        </span>
                                    </div>
                                    <ChevronRight
                                        size={14}
                                        className={`transition-transform duration-300 ${isActive ? 'translate-x-1' : 'opacity-0 group-hover:opacity-100 group-hover:translate-x-1'}`}
                                    />
                                </Link>
                            );
                        })}
                    </nav>
                </div>


            </div>
        </aside>
    );
};

export default Sidebar;
